ProjectALife.DialogueShards["scenes_any_1"] = {
{"fw_ld4_arguments_a_0001","any",2,"reg=civilian,family,worker,rescue",{1,"You ate the last of the crackers, didn't you? DIDN'T YOU?",2,"I was starving, Carol, I was gonna tell you!",1,"When? After they were gone?!",2,"God, I'm sorry... I'll find us more, I promise"}},
{"fw_ld4_arguments_a_0002","any",2,"reg=civilian,family,worker,rescue",{1,"I'm telling you, we should've gone north",2,"North?! North is where all the sirens were, are you out of your mind?",1,"At least there'd be soldiers, instead of this... this nothing",2,"Soldiers shoot first, Dale, you know that, you saw it",1,"Yeah, well, at least I'd be shot by somebody with a plan"}},
{"fw_ld4_arguments_a_0003","any",2,"reg=civilian,family,worker,rescue",{1,"Don't touch that, it's mine",2,"It's a can of corn, it's not a family heirloom",1,"It's MY can of corn, I found it, I carried it, I'm eating it",2,"Jesus, fine, hoard it, you greedy son of a bitch",1,"Call me whatever you want, I'm still eating it"}},
{"fw_ld4_arguments_a_0004","any",2,"reg=civilian,family,worker,rescue",{1,"Would you PLEASE stop humming?",2,"I'm not humming",1,"You're humming, it's that same stupid song, over and over",2,"It helps me think, alright? It keeps the quiet away",1,"...yeah, okay, fine, hum, just... hum something else"}},
{"fw_ld4_arguments_a_0005","any",2,"reg=civilian,family,worker,rescue|world=road",{1,"You're going to get us killed with that mouth",2,"I didn't say anything!",1,"You said 'hello' to a stranger on an open road, that's saying something",2,"He looked friendly! He looked lost!",1,"Lost people have guns too, you idiot"}},
{"fw_ld4_arguments_a_0006","any",2,"reg=civilian,family,worker,rescue",{1,"Whose turn is watch?",2,"Yours",1,"No, it was mine last night",2,"You slept through half of it, so technically I never got relieved",1,"Oh, go to hell, I'm going, I'm going, happy?"}},
{"fw_ld4_arguments_a_0007","any",2,"reg=civilian,family,worker,rescue",{1,"You said you'd fix the radio",2,"I said I'd TRY, there's a big difference",1,"It's been three days",2,"It's a hunk of junk with half its guts missing, what do you want from me?",1,"I want to hear a human voice that isn't yours, no offense",2,"Oh, none taken, that's nice, real nice"}},
{"fw_ld4_arguments_a_0008","any",2,"reg=civilian,family,worker,rescue",{1,"Stop looking at me like that",2,"Like what?",1,"Like I'm going to turn on you, like I'm bitten, like I'm already dead",2,"I'm just scared, okay? Everybody's scared",1,"Then say you're scared, don't stare at me like a cop"}},
{"fw_ld4_arguments_a_0009","any",2,"reg=civilian,family,worker,rescue",{1,"I'm not going back there",2,"We left medicine there. I don't know if any's left, but I keep thinking about it",1,"Marcus died there!",2,"I know, I was there. I'm not asking you to walk back into it just because I'm scared of running out",1,"...give me a minute, just a minute, I need to breathe"}},
{"fw_ld4_arguments_a_0010","any",2,"reg=civilian,family,worker,rescue",{1,"You keep saying it'll be fine",2,"Because it will be",1,"You don't know that, nobody knows that",2,"Then what do you want me to say?! That we're doomed?!",1,"I want you to say 'I don't know' for once, that's all"}},
{"fw_ld4_arguments_a_0011","any",2,"reg=civilian,family,worker,rescue",{1,"That's not how you tie a knot",2,"It's holding, isn't it?",1,"It's holding NOW, give it ten minutes",2,"Listen, I did two years in the Navy, I know knots",1,"Two years of cooking, Gary, we all know"}},
{"fw_ld4_arguments_a_0012","any",2,"reg=civilian,family,worker,rescue|day=10,3650|world=wind",{1,"Did you hear that? Out there?",2,"I didn't hear anything",1,"There it is again, listen",2,"...that's just the wind, you're jumpy",1,"Everyone's jumpy, that's the point, the whole damn point"}},
{"fw_ld4_arguments_a_0013","any",2,"reg=civilian,family,worker,rescue|day=10,3650|world=building",{1,"I miss coffee so much I could cry",2,"I miss my bed",1,"I miss being able to go to the bathroom without a gun in my hand",2,"Okay, you win, that's worse"}},
{"fw_ld4_arguments_a_0014","any",2,"reg=civilian,family,worker,rescue|day=10,3650",{1,"Do you ever think about just... stopping?",2,"Stopping what?",1,"Running, hiding, fighting, all of it",2,"Every day, honestly... every damn day",1,"Me too, I just wanted to hear someone else say it"}},
{"fw_ld4_arguments_a_0015","any",2,"reg=law,swat",{1,"You were supposed to cover the left",2,"I WAS covering the left!",1,"Then why did one of them get past?",2,"Because there were four of them and one of me, Frank",1,"Next time, tell me BEFORE you run out of ammo"}},
{"fw_ld4_arguments_a_0016","any",2,"reg=law,swat|world=building",{1,"Chief says stay inside the perimeter",2,"Chief says a lot of things",1,"He's the chief",2,"He's also hiding in the basement, so excuse me if I don't take notes"}},
{"fw_ld4_arguments_a_0017","any",2,"reg=law,swat",{1,"When's the last time you slept?",2,"Define slept",1,"Come on, Ray, you're a mess",2,"I'm fine, I'll sleep when this is over",1,"This won't be over, you know that, so sleep now"}},
{"fw_ld4_arguments_a_0018","any",2,"reg=law,swat",{1,"You shouldn't have shot him",2,"He was coming at me!",1,"He was waving a white flag, I saw it",2,"...I didn't see a flag, I didn't",1,"Yeah, well, we both have to live with it now"}},
{"fw_ld4_arguments_a_0019","any",2,"reg=law,swat|tmp=seasoned",{1,"You know what I miss? Writing speeding tickets",2,"You're kidding",1,"I'm serious, it was simple, someone breaks a rule, I write it down, justice",2,"And now?",1,"Now everyone's breaking every rule and there's nobody left to write it down"}},
{"fw_ld4_arguments_a_0020","any",2,"reg=military,elite",{1,"Sir, permission to speak freely?",2,"Granted",1,"This is a clusterfuck",2,"...yeah, it is, but keep it down, the men are listening",1,"Yes sir, sorry sir"}},
{"fw_ld4_arguments_a_0021","any",2,"reg=military,elite",{1,"Who left their weapon unattended?",2,"Wasn't me, Sergeant",1,"Wasn't me either",2,"Then it grew legs and walked away?! Find out, now!"}},
{"fw_ld4_arguments_a_0022","any",2,"reg=military,elite",{1,"We're out of rations by Thursday",2,"Then we find more by Thursday",1,"Sir, with respect, find them WHERE?",2,"Figure it out, Private, that's what I pay you for",1,"You don't pay me, sir",2,"Then you're getting a bargain"}},
{"fw_ld4_arguments_a_0023","any",2,"reg=military,elite",{1,"I want to go home",2,"We all do",1,"No, you don't get it, I MEAN IT, I want to go HOME",2,"Easy, kid, easy... home's gone, we're all we've got now",1,"...I know, I just needed to say it out loud"}},
{"fw_ld4_arguments_a_0024","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Who took my smokes?",2,"Not me",1,"You're lying, I can tell, you're sweating",2,"It's a hundred degrees, you moron, everybody's sweating",1,"Give me my smokes or I'll break your face"}},
{"fw_ld4_arguments_a_0025","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"You're skimming off the top, Tommy",2,"Am not",1,"I counted, there's three bullets short",2,"So I used 'em, big deal, you want a receipt?",1,"I want you to stop lying to me, that's all"}},
{"fw_ld4_arguments_a_0026","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Boss says we hit the farm tomorrow",2,"Boss says a lot of crap",1,"You wanna tell him that to his face?",2,"...no, no I do not",1,"Then shut up and sharpen your knife"}},
{"fw_ld4_arguments_a_0027","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Hey, that's my spot",2,"I don't see your name on it",1,"I'll carve it on your forehead if you want",2,"Ha, ha, alright, alright, calm down, I'll move"}},
{"fw_ld4_arguments_a_0028","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"You're drunk",2,"I'm celebrating",1,"Celebrating WHAT?",2,"Being alive, genius, it's a low bar but I cleared it"}},
{"fw_ld4_arguments_a_0029","any",2,"reg=outlaw,raider,gang,club,crime,prison|tmp=predator",{1,"Why'd you let her go?",2,"She wasn't worth a bullet",1,"She SAW us!",2,"She saw nothing, she was too scared to look, relax",1,"If she talks, it's on you"}},
{"fw_ld4_arguments_a_0030","any",2,"reg=family",{1,"Don't you take that tone with me",2,"Mama, I'm not a baby anymore!",1,"As long as you eat my food you're a baby",2,"Fine, I won't eat your food then!",1,"Fine!",2,"...Mama, I'm hungry"}},
{"fw_ld4_arguments_a_0031","any",2,"reg=family",{1,"Papa says we're staying here",2,"Papa doesn't know everything",1,"Don't let him hear you",2,"I'm just saying, we could try the school, maybe somebody's there",1,"...I'll talk to him, but don't get your hopes up"}},
{"fw_ld4_arguments_a_0032","any",2,"reg=family",{1,"Your sister's crying again",2,"I know, I can hear her",1,"Go sit with her",2,"I did, it doesn't help",1,"It helps more than you think, go on"}},
{"fw_ld4_big_e_0001","any",2,"reg=civilian,family,worker,rescue",{1,"You hear that?",2,"What?",1,"Nothing, it's quiet, too quiet, I hate it",2,"Then talk to me, say anything",1,"Pickle",2,"Pickle?",1,"I panicked, it's the first word that came"}},
{"fw_ld4_big_e_0002","any",2,"reg=civilian,family,worker,rescue",{1,"I think I'm gonna name my gun",2,"Why?",1,"Because it's the only friend who always shows up",2,"What's his name?",1,"Gerald",2,"Gerald?! You can't name a gun Gerald",1,"Gerald is a name that commands respect"}},
{"fw_ld4_big_e_0003","any",2,"reg=civilian,family,worker,rescue",{1,"If I die, take my boots",2,"I don't want your boots",1,"They're good boots",2,"They have holes in them",1,"Holes with character"}},
{"fw_ld4_big_e_0004","any",2,"reg=civilian,family,worker,rescue",{1,"Do you think about before?",2,"Constantly",1,"What do you think about?",2,"The smell of my wife's shampoo",1,"...God, I can't even remember mine"}},
{"fw_ld4_big_e_0005","any",2,"reg=civilian,family,worker,rescue",{1,"How long have you known him?",2,"Since third grade",1,"Wow",2,"He tried to eat my paste, and I threw it at him",1,"And you've been friends ever since?",2,"Best friends, even now, even here"}},
{"fw_ld4_big_e_0006","any",2,"reg=civilian,family,worker,rescue",{1,"Can I sit with you?",2,"Sure",1,"I don't want to talk",2,"Good, me neither",1,"This is nice",2,"Yeah, it is"}},
{"fw_ld4_big_e_0007","any",2,"reg=civilian,family,worker,rescue",{1,"You always sleep on your back?",2,"Why?",1,"You look like a corpse",2,"That's because I'm tired, and you're rude"}},
{"fw_ld4_big_e_0008","any",2,"reg=civilian,family,worker,rescue",{1,"Say something nice about me",2,"You have a good laugh",1,"That's it?",2,"What do you want, a medal?",1,"...a small medal, tin, if you have it"}},
{"fw_ld4_big_e_0009","any",2,"reg=civilian,family,worker,rescue",{1,"Why did you come with us?",2,"I didn't have anywhere else",1,"That's it?",2,"And I liked how you shared your last cracker with a stranger",1,"...that's the nicest thing anyone's said all month"}},
{"fw_ld4_big_e_0010","any",2,"reg=civilian,family,worker,rescue",{1,"You ever get used to the quiet?",2,"No",1,"I used to complain about the neighbors",2,"I'd give anything to hear their damn dog now",1,"Yeah. Me too"}},
{"fw_ld4_big_e_0011","any",2,"reg=civilian,family,worker,rescue",{1,"Name three things you miss",2,"Pizza, air conditioning, my sister's laugh",1,"Mine are coffee, my dog, and arguing about nothing",2,"Arguing about nothing is underrated"}},
{"fw_ld4_big_e_0012","any",2,"reg=civilian,family,worker,rescue",{1,"What would you tell your younger self?",2,"Eat more",1,"Eat more?",2,"Eat everything, every bite, because the cupboard won't always be full",1,"...deep, weirdly deep"}},
{"fw_ld4_big_e_0013","any",2,"reg=civilian,family,worker,rescue",{1,"You think there's a God?",2,"I think there's something",1,"Something good?",2,"Something quiet, which I guess is good enough",1,"I hope you're right"}},
{"fw_ld4_big_e_0014","any",2,"reg=civilian,family,worker,rescue",{1,"Do you want my last piece of gum?",2,"No, you keep it",1,"I insist",2,"I insist harder",1,"We're both idiots, let's split it"}},
{"fw_ld4_big_e_0015","any",2,"reg=civilian,family,worker,rescue",{1,"We should rest",2,"Not yet",1,"Why not?",2,"Because if I stop, I'll realize how tired I am, and then I won't be able to start again",1,"...okay, a little further"}},
{"fw_ld4_big_e_0016","any",2,"reg=civilian,family,worker,rescue",{1,"I like your jacket",2,"It's my husband's",1,"It looks good on you",2,"He'd laugh, he looked like a scarecrow in it",1,"Then you wear it better"}},
{"fw_ld4_big_e_0017","any",2,"reg=civilian,family,worker,rescue",{1,"Guess what I found?",2,"What?",1,"A harmonica",2,"Do you play?",1,"No",2,"Then give it here, I'll learn, how hard can it be?"}},
{"fw_ld4_big_e_0018","any",2,"reg=civilian,family,worker,rescue",{1,"How many fingers am I holding up?",2,"Three",1,"Four",2,"You're holding up three",1,"I was testing you",2,"I'm exhausted, I don't have time for tests"}},
{"fw_ld4_big_e_0019","any",2,"reg=civilian,family,worker,rescue",{1,"Don't die on me",2,"I won't",1,"Promise",2,"I'll do my best",1,"That's not a promise",2,"It's the best one I've got"}},
{"fw_ld4_big_e_0020","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"I messed up today",2,"How?",1,"I made too much noise, I almost got us killed",2,"But you didn't",1,"By luck",2,"Luck counts, next time you'll be quieter"}},
{"fw_ld4_big_e_0021","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"Is this what being an adult feels like?",2,"What?",1,"Being tired and scared and responsible all at once",2,"Yeah, pretty much, except usually there's TV"}},
{"fw_ld4_big_e_0022","any",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"I used to be a plumber",2,"Useful",1,"Not now, nobody needs a toilet fixed",2,"You'd be surprised how much I miss toilets",1,"I'd fix one for you, free, in a heartbeat"}},
{"fw_ld4_big_e_0023","any",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"How's your faith?",2,"Cracked, patched, cracked again",1,"Mine's in the same shape",2,"We're a matching set of broken, then"}},
{"fw_ld4_big_e_0024","any",2,"reg=law,swat|world=vehicle,road",{1,"Remember the night shifts out on the highway?",2,"When the truck driver tried to pass me a bribe in a tuna sandwich?",1,"The best tuna sandwich of my life",2,"You took it?",1,"I took it, I ate it, and I still gave him the ticket"}},
{"fw_ld4_big_e_0025","any",2,"reg=law,swat",{1,"You write a good report",2,"Thanks",1,"You write the worst handwriting I've ever seen",2,"Thanks again"}},
{"fw_ld4_big_e_0026","any",2,"reg=law,swat",{1,"What's the first thing you'll do after?",2,"Sleep for three days",1,"Then?",2,"Then take my kids fishing, and not catch anything, and not mind"}},
{"fw_ld4_big_e_0027","any",2,"reg=law,swat",{1,"The chief wants us back at the station by dark",2,"Why?",1,"Safer",2,"Is it?",1,"Safer than out here, which isn't saying much"}},
{"fw_ld4_big_e_0028","any",2,"reg=law,swat",{1,"Do you ever feel like quitting?",2,"Every hour",1,"And?",2,"And then I remember someone's counting on me, and I don't"}},
{"fw_ld4_big_e_0029","any",2,"reg=military,elite",{1,"Private, why are you smiling?",2,"Remembered finding an unopened pack of gum, sir",1,"Tell me you shared it",2,"Every piece, sir",1,"Then, Private, nice work"}},
{"fw_ld4_big_e_0030","any",2,"reg=military,elite",{1,"Where did you grow up?",2,"Hazard, Kentucky",1,"Coal country",2,"My daddy's lungs didn't make it",1,"I'm sorry",2,"He used to say 'son, keep your head up and your boots dry', I think of that every day"}},
{"fw_ld4_big_e_0031","any",2,"reg=military,elite",{1,"Heard the lieutenant's wife is expecting",2,"When?",1,"In October",2,"Congratulations to him, and God help him",1,"He's terrified",2,"Good, it means he's human"}},
{"fw_ld4_big_e_0032","any",2,"reg=military,elite",{1,"What do you miss most about the Army before all this?",2,"Having someone to tell me what to do",1,"That's the worst answer",2,"It's the honest one"}},
{"fw_ld4_big_e_0033","any",2,"reg=military,elite",{1,"Nobody tells you how heavy a rifle gets",2,"After eight hours",1,"After ten minutes",2,"After the first week, you learn to love the weight"}},
{"fw_ld4_big_e_0034","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Hey, what's your real name?",2,"Why?",1,"Because I'm sick of calling you 'Hey'",2,"It's Walter",1,"Walter? Walter?! You look like a Rex",2,"My mother wanted a Rex, she got a Walter"}},
{"fw_ld4_big_e_0035","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"What do you want?",2,"To be left alone",1,"Yeah, everybody wants that - try again",2,"Steak, a long nap... happy now?"}},
{"fw_ld4_big_e_0036","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Who was it you knew who always asked strangers for a light?",2,"My brother. Just liked an excuse to talk",1,"Sounds like somebody worth knowing",2,"He was. Kept a nice lighter, hardly used it",1,"Where's he?",2,"In a better place, I hope, I'm still looking for one myself"}},
{"fw_ld4_big_e_0037","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Why are we always on the move?",2,"Because the minute we stop, they catch up",1,"Who's they?",2,"The dead, the law, the debt, take your pick",1,"All of the above, then"}},
{"fw_ld4_big_e_0038","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Hey, wanna see a trick?",2,"No",1,"Come on",2,"Last time you set your sleeve on fire",1,"That was ONE time",2,"One time is plenty"}},
{"fw_ld4_big_e_0039","any",2,"reg=family|hour=20,5",{1,"Papa, why do the stars twinkle?",2,"Because they're happy to see us",1,"Even now?",2,"Especially now, little one"}},
{"fw_ld4_big_e_0040","any",2,"reg=family",{1,"Mama, I had a bad dream",2,"Come here, tell me",1,"There was a monster",2,"Was it big?",1,"Really big",2,"Well, I'm bigger, and I'm your mama, and I say it can't come in"}},
{"fw_ld4_big_e_0041","any",2,"reg=family",{1,"Your grandfather loved this song",2,"What song?",1,"The one with the whistle",2,"Can you whistle it?",1,"I'll try, I've lost my teeth, but I'll try"}},
{"fw_ld4_big_e_0042","any",2,"reg=family",{1,"Is there more bread?",2,"Just crumbs",1,"I'll take the crumbs",2,"Here, little man, the best crumbs in the house"}},
{"fw_ld4_comfort_a_0001","any",2,"reg=civilian,family,worker,rescue",{1,"You're humming",2,"Am I?",1,"Is that 'Wichita Lineman'?",2,"Yeah, my dad played it every Sunday",1,"Keep going, it's nice",2,"I only know the first verse",1,"Hum the first verse again"}},
{"fw_ld4_comfort_a_0002","any",2,"reg=civilian,family,worker,rescue",{1,"Sing something",2,"I can't sing",1,"Neither can I, that's why it's funny",2,"Ugh, fine... 'Row, row, row your boat'...",1,"Gently down the stream...",2,"...merrily, merrily, merrily, merrily"}},
{"fw_ld4_comfort_a_0003","any",2,"reg=civilian,family,worker,rescue|world=window,building",{1,"Can't sleep?",2,"Every time I close my eyes I see it",1,"Come here, tell me what you see",2,"It doesn't help",1,"Then tell me what you wish you saw instead",2,"A kitchen, with yellow curtains, and coffee on the stove"}},
{"fw_ld4_comfort_a_0004","any",2,"reg=civilian,family,worker,rescue",{1,"Do you want me to hold your hand?",2,"Is that weird?",1,"No. I'm scared too. I'd like somebody to hold mine",2,"Thanks... didn't think anybody else was"}},
{"fw_ld4_comfort_a_0005","any",2,"reg=civilian,family,worker,rescue",{1,"You did good today",2,"I froze",1,"You froze for two seconds and then you moved, that's good",2,"Two seconds is a lifetime",1,"We all get two seconds, you spent yours moving"}},
{"fw_ld4_comfort_a_0006","any",2,"reg=civilian,family,worker,rescue",{1,"Say it, say what you're thinking",2,"I'm thinking that we're going to die",1,"Not today",2,"How could you know that?",1,"I don't, but saying it out loud doesn't help, and I need you to keep walking"}},
{"fw_ld4_comfort_a_0007","any",2,"reg=civilian,family,worker,rescue",{1,"Hey, hey, look at me",2,"I'm looking",1,"You're not alone, okay? I'm right here",2,"I know, I know, it's just... it's so quiet",1,"Then let's make a little noise, tell me something dumb"}},
{"fw_ld4_comfort_a_0008","any",2,"reg=civilian,family,worker,rescue",{1,"I made soup",2,"With what?",1,"Don't ask",2,"I'm asking",1,"Water, salt, and a bouillon cube I found in a coat",2,"It's the best soup I've ever had, don't tell anyone"}},
{"fw_ld4_comfort_a_0009","any",2,"reg=civilian,family,worker,rescue",{1,"Could you pray with me?",2,"I don't know how",1,"Just hold my hand, I'll do the talking",2,"Alright... don't let go though"}},
{"fw_ld4_comfort_a_0010","any",2,"reg=civilian,family,worker,rescue",{1,"Dear Lord, thank you for this day, and the food we have, and the people around us",2,"Amen",1,"And please keep the others safe, wherever they are",2,"Amen, amen"}},
{"fw_ld4_comfort_a_0011","any",2,"reg=civilian,family,worker,rescue",{1,"I used to hate going to church",2,"Why?",1,"Because it was boring, and the pews hurt",2,"And now?",1,"Now I'd give anything to sit on a hard pew and hear a boring sermon"}},
{"fw_ld4_comfort_a_0012","any",2,"reg=civilian,family,worker,rescue",{1,"Let me braid your hair",2,"What for?",1,"It'll keep it out of your eyes, and it'll make me feel useful",2,"Sure, just not too tight",1,"Hold still, just like my grandma taught me"}},
{"fw_ld4_comfort_a_0013","any",2,"reg=civilian,family,worker,rescue|world=snow",{1,"What's your earliest memory?",2,"Sitting on my daddy's shoulders at a parade",1,"Which parade?",2,"The Fourth of July, in Brandenburg, I got a flag and a snow cone",1,"That's a good one, keep it safe"}},
{"fw_ld4_comfort_a_0014","any",2,"reg=civilian,family,worker,rescue",{1,"Do you think they miss us?",2,"Who?",1,"The dead, the ones who didn't make it",2,"I think they'd want us to keep going",1,"That's what I tell myself too"}},
{"fw_ld4_comfort_a_0015","any",2,"reg=civilian,family,worker,rescue",{1,"I wish I'd hugged him more",2,"Everyone says that",1,"Because everyone's right",2,"Then hug me, now, and we'll call it even"}},
{"fw_ld4_comfort_a_0016","any",2,"reg=civilian,family,worker,rescue",{1,"It's okay to cry, you know",2,"I know, I just don't want to start",1,"Why not?",2,"Because I won't stop",1,"Then don't stop, I've got all night"}},
{"fw_ld4_comfort_a_0017","any",2,"reg=civilian,family,worker,rescue|tmp=fresh|hour=4,11",{1,"I want my mom",2,"Me too",1,"I'm twenty-two years old and I want my mom",2,"That's allowed",1,"Is it?",2,"I'm twenty-six and I wrote 'Mom' in the dirt this morning"}},
{"fw_ld4_comfort_a_0018","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"Do you think there are still birds?",2,"There must be",1,"I haven't heard any",2,"Maybe they're hiding too",1,"Maybe they're waiting for it to be quiet"}},
{"fw_ld4_comfort_a_0019","any",2,"reg=law,swat",{1,"Rough day?",2,"The worst",1,"You wanna say anything about it?",2,"Not yet. Ask me again tomorrow",1,"Anytime, partner"}},
{"fw_ld4_comfort_a_0020","any",2,"reg=law,swat",{1,"I'm not sleeping well",2,"Nobody is",1,"But you look fine",2,"I'm good at faking it",1,"Teach me"}},
{"fw_ld4_comfort_a_0021","any",2,"reg=military,elite",{1,"Hey, Private, you good?",2,"Yes, Sergeant",1,"Don't 'yes Sergeant' me, you good?",2,"...no, not really",1,"That's okay, none of us are, sit with me"}},
{"fw_ld4_comfort_a_0022","any",2,"reg=military,elite",{1,"You ever write to your folks?",2,"I wrote one, I don't know if it'll ever reach them",1,"What'd it say?",2,"'I'm fine, I love you, I'll see you soon'",1,"Perfect, that's all a letter needs"}},
{"fw_ld4_comfort_a_0023","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Why're you sitting alone?",2,"Thinking",1,"About what?",2,"About my sister, she's out there somewhere",1,"Want me to help look?",2,"...yeah, actually, I do"}},
{"fw_ld4_comfort_a_0024","any",2,"reg=outlaw,raider,gang,club,crime,prison|world=cold",{1,"Hey, take my jacket",2,"I'm fine",1,"You're shivering",2,"...thanks, I guess you're not so bad"}},
{"fw_ld4_comfort_a_0025","any",2,"reg=family",{1,"Come sit on my lap, little one",2,"I'm too big",1,"You're never too big for your Nana's lap",2,"Okay, but only a little while"}},
{"fw_ld4_comfort_a_0026","any",2,"reg=family|hour=20,5",{1,"Sing me the song about the moon",2,"Which one?",1,"The one with the cow jumping over it",2,"That's a rhyme, silly",1,"Sing it anyway, please"}},
{"fw_ld4_comfort_a_0027","any",2,"reg=family",{1,"Papa, why are you awake?",2,"Just watching over everyone",1,"Can I help?",2,"Go to sleep, little man, tomorrow you can watch over me"}},
{"fw_ld4_crim_a_0001","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"How many bullets we got?",2,"Enough",1,"That's not a number",2,"It's the only number that matters, Dwayne"}},
{"fw_ld4_crim_a_0002","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"I used to run numbers outside Shively",2,"Yeah? What happened to that?",1,"Same thing that happened to everything else, it died, and nobody gave a damn",2,"Ha, true, true"}},
{"fw_ld4_crim_a_0003","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"You think the boss ever sleeps?",2,"He sleeps with his boots on",1,"How d'you know that?",2,"Because I tried to steal them once",1,"And?",2,"And I sleep with a limp now"}},
{"fw_ld4_crim_a_0004","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"There's a girl at the camp I like",2,"Which one?",1,"The one with the red bandana",2,"She'd cut your throat for a can of peaches",1,"...I think that's why I like her"}},
{"fw_ld4_crim_a_0005","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Pass the bottle",2,"It's empty",1,"Then why are you holding it?",2,"Comfort, man, it's called comfort"}},
{"fw_ld4_crim_a_0006","any",2,"reg=outlaw,raider,gang,club,crime,prison|world=cars",{1,"I never wanted this life",2,"Sure you didn't",1,"I'm serious, I wanted to be a mechanic, work on Fords",2,"Then be a mechanic",1,"...there are no cars, genius",2,"There's always cars somewhere, shut up and drive"}},
{"fw_ld4_crim_a_0007","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"You ever kill anybody?",2,"What kind of a question is that?",1,"A real one",2,"...once, before all this, I was nineteen, drunk, stupid",1,"How's that sit with you?",2,"Worse than all the rest of it, honestly"}},
{"fw_ld4_crim_a_0008","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"This place has a good feel to it",2,"It has a stink to it",1,"That's what a good feel smells like, dummy",2,"Then I've been spoiled by clean air"}},
{"fw_ld4_crim_a_0009","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Look at those idiots, wandering around like they own the place",2,"They're scared",1,"Of us?",2,"Of everything, that's their problem, and our opportunity",1,"...you're a poet, Marty"}},
{"fw_ld4_crim_a_0010","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Don't tell the boss, but I miss my mom",2,"Dude",1,"I know, I know",2,"...mine made the best pound cake in Hardin County",1,"Shut up, you're making me cry"}},
{"fw_ld4_crim_a_0011","any",2,"reg=outlaw,raider,gang,club,crime,prison|world=vehicle",{1,"I got a plan",2,"Last time you had a plan we lost a truck",1,"This time there's no truck to lose",2,"Fine, what's the plan?",1,"We go in, we take stuff, we leave",2,"Wow, so just what we always do"}},
{"fw_ld4_crim_a_0012","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Hey, you owe me ten bucks",2,"Money's worthless",1,"Then you owe me ten worthless bucks",2,"Fine, here, a bundle of dead presidents, spend it wisely"}},
{"fw_ld4_crim_a_0013","any",2,"reg=outlaw,raider,gang,club,crime,prison|world=road",{1,"Wanna hear something funny?",2,"Always",1,"Cops used to chase me for jaywalking",2,"And now?",1,"Now I'm the only guy on this road with a badge, and I stole it",2,"Ha, 'Officer', you look good in blue"}},
{"fw_ld4_crim_a_0014","any",2,"reg=outlaw,raider,gang,club,crime,prison|tmp=predator",{1,"Watch this",2,"Don't, we need the guy",1,"He's slow, and he's loud, and he's an idiot",2,"And he knows where the stash is",1,"...fine, I'll wait, but I'm gonna enjoy it later"}},
{"fw_ld4_crim_a_0015","any",2,"reg=outlaw,raider,gang,club,crime,prison|tmp=predator",{1,"She begged",2,"They all beg",1,"But this one begged WELL, I almost let her go",2,"Almost?",1,"Almost"}},
{"fw_ld4_crim_a_0016","any",2,"reg=outlaw,raider,gang,club,crime,prison|tmp=predator",{1,"Pretty soon, there won't be anybody left to rob",2,"There'll always be somebody",1,"Yeah? Who?",2,"The guy who's holding what you want, that's who"}},
{"fw_ld4_crim_a_0017","any",2,"reg=outlaw,raider,gang,club,crime,prison|hour=21,4",{1,"Quiet tonight",2,"Quiet's good, quiet means no dead, no cops, no nothing",1,"Quiet makes me nervous",2,"Everything makes you nervous, Billy"}},
{"fw_ld4_crim_a_0018","any",2,"reg=outlaw,raider,gang,club,crime,prison|hour=21,4",{1,"If we ever have to share a blanket, you're keeping your feet to yourself",2,"That's a lot of rules for an imaginary blanket",1,"I'm getting the argument out of the way early",2,"Fine, but no funny business",1,"I wouldn't dare"}},
{"fw_ld4_culture_a_0001","any",2,"reg=civilian,family,worker,rescue",{1,"You a Wildcats fan?",2,"Born and raised, my daddy had season tickets",1,"Rupp Arena, huh?",2,"He cried when they lost in '84, cried like a baby",1,"Next year, right?",2,"Next year, there's always a next year"}},
{"fw_ld4_culture_a_0002","any",2,"reg=civilian,family,worker,rescue|world=vehicle",{1,"What were you watching on TV last week?",2,"The ball game, mostly, and a rerun of something with a talking car",1,"I miss reruns",2,"Weird, but I miss commercials",1,"The one with the dancing raisins?",2,"Dancing raisins, yes, God, I'm tearing up"}},
{"fw_ld4_culture_a_0003","any",2,"reg=civilian,family,worker,rescue",{1,"Do you still have your Walkman?",2,"Dead batteries, three tapes, one has a mix from my girlfriend",1,"Can you still read the label?",2,"Her handwriting, it says 'For when you miss me'",1,"...that's rough, buddy"}},
{"fw_ld4_culture_a_0004","any",2,"reg=civilian,family,worker,rescue",{1,"My cousin wanted to see the new dinosaur movie",2,"Did he?",1,"He saw it twice, then moved to Ohio",2,"Hope he's okay up there",1,"He wasn't the type to panic, so, probably"}},
{"fw_ld4_culture_a_0005","any",2,"reg=civilian,family,worker,rescue",{1,"Did you vote for the new president?",2,"My wife did, I didn't",1,"Do you regret it?",2,"I regret everything today, so, yes, no, I don't know",1,"...I think he's busy"}},
{"fw_ld4_culture_a_0006","any",2,"reg=civilian,family,worker,rescue",{1,"I had a pager",2,"A real one?",1,"Black, with a belt clip, I felt like a doctor",2,"Did anyone page you?",1,"Mostly my mother, 'call home,' that's all it ever said",2,"I'd give anything to get that page now"}},
{"fw_ld4_culture_a_0007","any",2,"reg=civilian,family,worker,rescue|world=vehicle",{1,"Remember the Fourth of July parade?",2,"Brandenburg or Muldraugh?",1,"Muldraugh, the one with the fire truck and the clown",2,"The clown scared me",1,"He scared everyone, that was his talent"}},
{"fw_ld4_culture_a_0008","any",2,"reg=civilian,family,worker,rescue",{1,"Cassettes are better than CDs",2,"Why?",1,"Because you can make a mixtape, and a mixtape is a love letter",2,"A CD burner's coming, they say",1,"Not in my lifetime, hah"}},
{"fw_ld4_culture_a_0009","any",2,"reg=civilian,family,worker,rescue",{1,"What did you do for fun?",2,"Bowling league, Tuesday nights",1,"Were you good?",2,"Terrible, but the nachos were great",1,"Strikes and nachos, a good life"}},
{"fw_ld4_culture_a_0010","any",2,"reg=civilian,family,worker,rescue",{1,"Did you ever go to the county fair?",2,"Every year, I won a stuffed pig once",1,"Throwing rings?",2,"Shooting water into a clown's mouth, I'm underrated",1,"Do you still have the pig?",2,"Somewhere in a box, with my diploma"}},
{"fw_ld4_culture_a_0011","any",2,"reg=civilian,family,worker,rescue",{1,"Back in high school, I played the trumpet",2,"In the marching band?",1,"Third chair, I mostly held the note and prayed",2,"Can you still play?",1,"I don't have the trumpet, but I can hum the first four bars of the fight song"}},
